css:
.cosmic-element {
  position: absolute;
  inset: 0;
  pointer-events: none;
  filter: url(#cosmic-texture);
  z-index: 1;
  mix-blend-mode: lighten;
}

.stars-layer {
  position: absolute;
  inset: 0;
  background-image: radial-gradient(#ffffff11 1px, transparent 1px),
    radial-gradient(#00ffe033 1px, transparent 1px);
  background-size: 4px 4px;
  animation: twinkle 4s infinite alternate ease-in-out;
  opacity: 0.05;
}

.wind-wave {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    45deg,
    rgba(255, 255, 255, 0.015) 0px,
    rgba(0, 255, 255, 0.03) 1px,
    transparent 3px
  );
  background-size: 300% 300%;
  animation: windShift 10s ease-in-out infinite;
}

.ice-crystal {
  position: absolute;
  inset: 0;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='://www.w3.org/2000/svg' width='100' height='100'><line x1='0' y1='0' x2='100' y2='100' stroke='%2300ffff' stroke-opacity='0.05'/><line x1='100' y1='0' x2='0' y2='100' stroke='%2300ffff' stroke-opacity='0.05'/></svg>");
  background-size: 80px 80px;
  animation: iceDrift 15s linear infinite;
  mix-blend-mode: screen;
  opacity: 0.05;
}
